def review(r,audit,resources):
 gid=r['game']['game_id'];events=r.get('events',[]);good=[(i,e) for i,e in enumerate(events) if accepted(e)];initial=next((body(e) for _,e in good if e.get('request',{}).get('command',e.get('request',{}).get('method'))=='init'),{});last=body(good[-1][1]) if good else {};opts=initial.get('options',{});config=initial.get('config',{});currency=opts.get('currency',initial.get('currency_attributes'));schema={k:v for k,v in opts.items() if k in BET_FIELDS};failed=audit.get(gid,{}).get('failed',0);kind,next_step=classify(gid,r,last,failed)
 rejected=[dict(event=i,status=e.get('status'),command=e.get('request',{}).get('command',e.get('request',{}).get('method')),errors=e.get('response',{}).get('errors'),rpc_error_present=bool(e.get('response',{}).get('error'))) for i,e in enumerate(events) if not accepted(e)]
 flow=last.get('flow') or {};game=last.get('game');game=game if isinstance(game,dict) else {};evidence=[str(p.relative_to(ROOT)).replace('\\','/') for p in sorted((ROOT/'protocols').glob(gid+'.*.json'))];static=resources.get(gid,{});signals=[]
 for item in static.get('resources',[]):
  if item.get('status')!='cached_not_executed':continue
  cache=PRIVATE/'research/frontends'/gid/item['cache_file'];raw=cache.read_bytes();source=raw.decode('utf8');signals.append(dict(path=item['path'],sha256=hashlib.sha256(raw).hexdigest(),source_markers={key:source.count(key) for key in ['product_round','selectedWinLines','custom_req','purchased_feature','System.register','cclegacy'] if key in source}))
 if config:schema['jsonrpc_config']={k:v for k,v in config.items() if k in ['bet_limits','default_bet','purchased_features']}
 return dict(game_id=gid,title=r['game']['title'],status=r['status'],report='live/'+gid+'.json',reason=r.get('reason'),error_type=r.get('error_type'),category=kind,next_step=next_step,evidence=dict(event_count=len(events),accepted_non_init_events=sum(e['request'].get('command',e['request'].get('method'))!='init' for _,e in good),declared_modes=len(r.get('declared_modes',[])),closed_modes=[m['mode']['name'] for m in r.get('modes',[]) if m['status']=='closed'],last_accepted_event=good[-1][0] if good else None,last_observed_state=flow.get('state',game.get('state')),last_available_commands=flow.get('available_actions',last.get('available_commands',[])),currency=currency,balance_schema=type(initial.get('balance')).__name__,native_bet_schema=schema,rejections=rejected,source_references=evidence,static_client_sources=signals,failed_native_checks=failed),limits=['A published purchased_features allowlist does not independently prove a visible purchasable mode.','No guesses about raw monetary units from field names; use currency.subunits and the source conversion.','No automatic replay of a received or uncertain operation.'])
if __name__=='__main__':
 state=json.loads((ROOT/'run-state.json').read_text(encoding='utf8'))
 if state.get('active_game'):raise RuntimeError('Snapshot only at a between-game checkpoint')
 audit={r['game_id']:r for r in json.loads((ROOT/'live-audit.json').read_text(encoding='utf8'))['reports']};resource_manifest=json.loads((ROOT/'remaining-rpc-resources.json').read_text(encoding='utf8'));resources={r['game_id']:r for r in resource_manifest['results']};slot_ids={g['game_id'] for g in json.loads((ROOT/'catalog-live.json').read_text(encoding='utf8'))['games'] if g.get('game_type')=='Slots' and g.get('game_id')};reports=[json.loads(p.read_text(encoding='utf8')) for p in sorted((ROOT/'live').glob('*.json'))];reports=[r for r in reports if r['game']['game_id'] in slot_ids];pending=[review(r,audit,resources) for r in reports if r['status']!='complete_declared_modes'];recent=[dict(game_id=r['game']['game_id'],status=r['status'],closed_modes=sum(m['status']=='closed' for m in r.get('modes',[]))) for r in reports if r['game']['game_id'] in RECENT];counts=dict(collections.Counter(x['category'] for x in pending));result=dict(reviewed_at=now(),provider='BGaming',review_kind='Current slot financial/availability findings from native captures and sources; no gameplay calls by this script',games_with_reports=len(reports),complete_declared_modes=sum(r['status']=='complete_declared_modes' for r in reports),remaining=len(pending),categories=counts,recently_completed=recent,known_unavailable_catalog_products=24,unavailable_evidence='catalog-unavailable.json',static_resource_manifest='remaining-rpc-resources.json',games=pending)
