 lines=['# Revisión individual de los pendientes BGaming','',f"Fecha UTC: {result['reviewed_at']}",'',f"Se revisaron {len(pending)} informes con incidencias de conciliación o disponibilidad. El estado de ejecución está separado en slot-results.json. Hay {result['complete_declared_modes']} slots completos de 220 con demo pública; otros 24 slots del catálogo no tienen enlace público de demo capturado. Revisado no significa probado ni resuelto.",'','Los recuentos se reconstruyen de las capturas actuales. Los modos con needs_trigger tienen un intento registrado y una condición aleatoria pendiente; no deben confundirse con compras ejecutadas. Las discrepancias nativas permanecen visibles.','', 'Consultar live-audit.json para las comprobaciones y diferencias actuales. Las dos solicitudes históricas inciertas continúan archivadas como desconocidas; interruption-audit.json identifica cualquier operación activa incierta.','','## Qué falta por juego','','Cada fila enlaza su captura saneada. `remaining-review.json` incluye esquema monetario nativo, último estado aceptado, rechazos, comprobaciones y referencias/hash de fuente. Los archivos HTML/JS completos permanecen en la carpeta privada.','','| Juego | Causa verificada o límite observado | Próximo paso |','|---|---|---|']
 for entry in pending:lines.append('| ['+entry['game_id']+']('+entry['report']+') | '+entry['category']+' | '+entry['next_step'].replace('|','/')+' |')
 lines+=['','## Reproducción','','`python -X utf8 review_remaining.py` reconstruye este informe sin red ni apuestas. Las capturas recibidas y sus hashes se conservan; las hipótesis y pasos pendientes no se contabilizan como ejecución satisfactoria.','', 'Los recursos reales de los clientes JSON-RPC revisados se conservan por separado. Un 404 de definitions.json/game.min.js o un fallo al interpretar un recurso como JSON no demuestra un fallo de la API: algunos clientes usan varios scripts, entradas con hash o SystemJS. Las listas genéricas de nombres de características en init tampoco demuestran nueve compras disponibles.']
 (ROOT/'REMAINING-REVIEW.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print(json.dumps({k:v for k,v in result.items() if k not in ['games','recently_completed']},ensure_ascii=False));print('Recent',recent)
